  const closePanel = useCallback(() => setActivePanel(null), []);

  const openPanel = useCallback(
    (panel: WorkspacePanelId) => {
      if (setupOpen) {
        closeSetup();
      }
      setActivePanel(panel);
    },
    [setupOpen, closeSetup],
  );

  const stopStreaming = useCallback(() => {
    abortRef.current?.abort();
  }, []);

  const sendMessage = useCallback(
    async (text: string) => {
      const trimmed = text.trim();
      if (!trimmed || streaming) {
        return;
      }

      const history: ChatMessage[] = [...messages, { role: "user", content: trimmed }];
      const assistantIndex = history.length;
      setMessages([...history, { role: "assistant", content: "", parts: [] }]);
      setStreaming(true);
      setThinkingPhase("health_check");
      setOfflineReply(false);
      setToolActivity([]);

      const controller = new AbortController();
      abortRef.current = controller;

      let content = "";
      let parts: ChatPart[] = [];
      let failure: StudioError | null = null;
      let terminal = false;
      let stopped = false;

      // Prose is appended to the open text part; a surface opens a new one, so
      // the transcript keeps the agent's order instead of gathering all prose
      // above all cards.
      const appendText = (text: string) => {
        if (!text) {
          return;
        }
        content += text;
        const last = parts[parts.length - 1];
        parts =
          last?.kind === "text"
            ? [...parts.slice(0, -1), { kind: "text", text: last.text + text }]
            : [...parts, { kind: "text", text }];
      };

      const publish = () => {
        setMessages((prev) => {
          const next = [...prev];
          next[assistantIndex] = {
            role: "assistant",
            content,
            parts: [...parts],
            ...(failure ? { error: failure, retryText: trimmed } : {}),
          };
          return next;
        });
      };

      const handleEvent = (event: RawSseEvent) => {
        switch (event.event) {
          case "status": {
            const phase = String(event.data.phase ?? "");
            setThinkingPhase(phase);
            if (phase === "offline") {
              setOfflineReply(true);
            }
            break;
          }
          case "delta": {
            appendText(String(event.data.text ?? ""));
            publish();
            break;
          }
          case "ui": {
            // Validate again on arrival: the connection is local but the
            // renderer must never trust a shape it has not checked.
            const parsed = parseUiSpec(event.data.spec, catalogManifest());
            if (parsed.ok) {
              parts = [
                ...parts,
                { kind: "ui", id: String(event.data.id ?? `ui-${parts.length}`), node: parsed.node },
              ];
              publish();
            }
            break;
          }
          case "tool":
            setToolActivity((prev) => [
              ...prev,
              {
                name: String(event.data.name ?? ""),
                status: String(event.data.status ?? ""),
                preview: event.data.preview ? String(event.data.preview) : undefined,
              },
            ]);
            break;
          case "message": {
            terminal = true;
            content = String(event.data.content ?? content);
            const hasSurfaces = parts.some((part) => part.kind === "ui");
            if (!hasSurfaces) {
              parts = content ? [{ kind: "text", text: content }] : [];
            }
            publish();
            break;
          }
          case "conversation": {
            const id = String(event.data.id ?? "");
            if (id) {
              setConversationId(id);
            }
            break;
          }
          case "memory": {
            const observation = event.data.observation as Observation | undefined;
            if (observation?.id) {
              setMemory((prev) =>
                prev.some((item) => item.id === observation.id)
                  ? prev.map((item) => (item.id === observation.id ? observation : item))
                  : [...prev, observation],
              );
            }
            break;
          }
          case "canvas_dirty":
            void refreshCanvas();
            break;
          case "connector": {
            if (String(event.data.status ?? "") === "error") {
              const reason = String(event.data.error ?? "The connector could not be added.");
              setMessages((prev) => [
                ...prev,
                { role: "notice", content: `Connector failed: ${reason}` },
              ]);
            } else {
              setConnectorSuggestions((prev) => {
                const id = String(event.data?.preset ?? event.data?.name ?? "");
                if (!id || prev.includes(id)) {
                  return prev;
                }
                return [...prev, id];
              });
            }
            void refreshConnectors();
            break;
          }
          case "error": {
            terminal = true;
            failure = readStudioError(event.data.error);
            publish();
            break;
          }
          default:
            break;
        }
      };

      try {
        await streamChat(
          {
            base_url: settings.base_url,
            api_key: settings.api_key,
            model: settings.model_name,
            mcp_url: settings.mcp_url,
            messages: history,
            brief,
            ui_catalog: catalogManifest(),
            conversation_id: conversationId,
          },
          handleEvent,
          controller.signal,
        );
      } catch (error) {
        const aborted = (error as Error).name === "AbortError";
        if (aborted) {
          // An abort is the user's own doing: drop the empty placeholder, keep
          // the question, and report no failure — the assistant did not break.
          stopped = true;
          setMessages((prev) => {
            const next = [...prev];
            if (next.length && next[next.length - 1].role === "assistant" && !next[next.length - 1].content) {
              next.pop();
            }
            return next;
          });
        } else {
          terminal = true;
          failure = asStudioError(error);
          publish();
        }
      } finally {
        if (!terminal && !failure && !stopped) {
          // The stream ended without a message or an error: something failed
          // silently, and the user must still be told.
          failure = {
            code: "internal",
            message: "The assistant stopped before answering.",
            suggestion: "Try again — your question is still here.",
            retryable: true,
          };
          publish();
        }
        setStreaming(false);
        setThinkingPhase(null);
        abortRef.current = null;
      }
    },
    [
      messages,
      streaming,
      settings,
      brief,
      conversationId,
      refreshCanvas,
      refreshConnectors,
    ],
  );

  /** The single conversational exit from any lens. */
  const ask = useCallback(
    (intent: string) => {
      setActivePanel(null);
      void sendMessage(intent);
    },
    [sendMessage],
  );

  const refreshMemory = useCallback(async () => {
    setMemoryLoading(true);
    try {
      setMemory(await fetchMemory());
    } catch {
      /* memory is a convenience; the studio keeps working without it */
    } finally {
      setMemoryLoading(false);
    }
  }, []);

  const addObservation = useCallback(
    async (payload: AddObservationPayload) => {
      try {
        const observation = await apiAddObservation(payload);
        setMemory((prev) => [...prev, observation]);
        return observation;
      } catch {
        pushToast("error", "I couldn't save that context.");
        return null;
      }
    },
    [pushToast],
  );

  const updateObservation = useCallback(
    async (observationId: string, payload: UpdateObservationPayload) => {
      try {
        const observation = await apiUpdateObservation(observationId, payload);
        setMemory((prev) =>
          observation.status === "dismissed"
            ? prev.filter((item) => item.id !== observationId)
            : prev.map((item) => (item.id === observationId ? observation : item)),
        );
        return observation;
      } catch {
        pushToast("error", "I couldn't update that context.");
        return null;
      }
    },
    [pushToast],
  );

  const deleteObservation = useCallback(
    async (observationId: string) => {
      try {
        await apiDeleteObservation(observationId);
        setMemory((prev) => prev.filter((item) => item.id !== observationId));
      } catch {
        pushToast("error", "I couldn't forget that.");
      }
    },
    [pushToast],
  );

  const clearMemory = useCallback(async () => {
    try {
      await apiClearMemory();
      setMemory([]);
      setConversationId(null);
      setMessages([]);
      setToolActivity([]);
    } catch {
      pushToast("error", "I couldn't clear what I've learned.");
    }
  }, [pushToast]);

  const clearChat = useCallback(() => {
    abortRef.current?.abort();
    abortRef.current = null;
    setMessages([]);
    setToolActivity([]);
    setStreaming(false);
    setThinkingPhase(null);
    setOfflineReply(false);
    setConversationId(null);
    void apiCreateConversation()
      .then((conversation) =>
        setConversationId((current) => current ?? conversation.id),
      )
      .catch(() => undefined);
  }, []);

  // Initial hydration: env defaults, canvas, health probes.
  useEffect(() => {
    let cancelled = false;

    async function boot() {
      try {
        const defaults = await fetchConfig();
        if (!cancelled) {
          setSidecarReachable(true);
          if (localStorage.getItem(SETTINGS_KEY) === null) {
            saveSettings(defaults);
          }
        }
      } catch {
        if (!cancelled) {
          setSidecarReachable(false);
        }
      }
      if (cancelled) {
        return;
      }
      void refreshCanvas();
      void refreshConnectors();
      void refreshPresets();
      void refreshMemory();
      void fetchLatestConversation()
        .then(({ conversation, turns }) => {
          if (cancelled || !conversation || turns.length === 0) {
            return;
          }
          setConversationId(conversation.id);
          setMessages(
            turns
              .filter((turn) => turn.role === "user" || turn.role === "assistant")
              .map((turn) => ({
                role: turn.role as "user" | "assistant",
                content: turn.content,
                parts: turn.content ? [{ kind: "text", text: turn.content }] : [],
              })),
          );
        })
        .catch(() => undefined);
      void healthMcp(settings.mcp_url)
        .then((result) => {
          if (!cancelled) {
            setMcpReachable(result.reachable);
          }
        })
        .catch(() => undefined);
      void healthLlm({
        base_url: settings.base_url,
        api_key: settings.api_key,
        model: settings.model_name,
      })
        .then((result) => {
          if (!cancelled) {
            setLlmHealth(result);
          }
        })
        .catch(() => undefined);
    }

    void boot();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Health polling: the studio must notice that the model or the MCP server
  // came back without a reload, so the bar leaves "Local mode" on its own.
  useEffect(() => {
    const poll = () => {
      if (document.visibilityState === "visible") {
        void checkConnections();
      }
    };

    const timer = window.setInterval(poll, HEALTH_POLL_INTERVAL_MS);
    document.addEventListener("visibilitychange", poll);

    return () => {
      window.clearInterval(timer);
      document.removeEventListener("visibilitychange", poll);
    };
  }, [checkConnections]);

  // The canvas is one state, not four booleans: an empty board and a failed
  // board must never look the same.
  const canvas = canvasState.data;
  const canvasLoading = canvasState.kind === "loading";
  const canvasError = canvasState.kind === "error" ? canvasState.error : null;

  const value = useMemo<StudioContextValue>(
    () => ({
      settings,
      saveSettings,
      displayName,
      setDisplayName,
      brief,
      saveBrief,
      setupOpen,
      openSetup,
      closeSetup,
      canvas,
      canvasLoading,
      canvasCached,
      canvasState,
      canvasError,
      refreshCanvas,
      llmHealth,
      mcpReachable,
      sidecarReachable,
      checkConnections,
      messages,
      streaming,
      thinkingPhase,
      toolActivity,
      sendMessage,
      stopStreaming,
      clearChat,
      conversationId,
      memory,
      memoryLoading,
      refreshMemory,
      addObservation,
      updateObservation,
      deleteObservation,
      clearMemory,
      pushNotice,
      offlineReply,
      addStep,
      addOutcome,
      createJob,
      updateJob,
      deleteJob,
      updateStep,
      deleteStep,
      updateOutcome,
      deleteOutcome,
      activePanel,
      openPanel,
      closePanel,
      ask,
      toasts,
      pushToast,
      dismissToast,
      connectors,
      connectorsError,
      presets,
      presetError,
      refreshConnectors,
      refreshPresets,
      addConnector,
      deleteConnector,
      connectorSuggestions,
      dismissConnectorSuggestion,
      notifications,
      unreadNotificationCount,
      markNotificationAsRead,
      markAllNotificationsAsRead,
      dismissNotification,
      addNotification,
      simulateBackgroundEvent,
    }),
    [
      settings,
      saveSettings,
      displayName,
      setDisplayName,
      brief,
      saveBrief,
      setupOpen,
      openSetup,
      closeSetup,
      canvas,
      canvasLoading,
      canvasCached,
      canvasState,
      canvasError,
      refreshCanvas,
      llmHealth,
      mcpReachable,
      sidecarReachable,
      checkConnections,
      messages,
      streaming,
      thinkingPhase,
      toolActivity,
      sendMessage,
      stopStreaming,
      clearChat,
      conversationId,
      memory,
      memoryLoading,
      refreshMemory,
      addObservation,
      updateObservation,
      deleteObservation,
      clearMemory,
      pushNotice,
      offlineReply,
      addStep,
      addOutcome,
      createJob,
      updateJob,
      deleteJob,
      updateStep,
      deleteStep,
      updateOutcome,
      deleteOutcome,
      activePanel,
      openPanel,
      closePanel,
      ask,
      toasts,
      pushToast,
      dismissToast,
      connectors,
      connectorsError,
      presets,
      presetError,
      refreshConnectors,
      refreshPresets,
      addConnector,
      deleteConnector,
      connectorSuggestions,
      dismissConnectorSuggestion,
      notifications,
      unreadNotificationCount,
      markNotificationAsRead,
      markAllNotificationsAsRead,
      dismissNotification,
      addNotification,
      simulateBackgroundEvent,
    ],
  );

  return <StudioContext.Provider value={value}>{children}</StudioContext.Provider>;
}

export function useStudio(): StudioContextValue {
  const context = useContext(StudioContext);
  if (!context) {
    throw new Error("useStudio must be used within a StudioProvider");
  }
  return context;
}

